ALTER TABLE public.messaging_settings ADD COLUMN interview_recording_enabled boolean NOT NULL DEFAULT false, ADD COLUMN recording_retention_days integer NOT NULL DEFAULT 90 CHECK (recording_retention_days IN (30,60,90,180));
CREATE TABLE public.interview_recordings (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), store_id uuid NOT NULL REFERENCES public.dealerships(id), applicant_id uuid NOT NULL REFERENCES public.applications(id), interview_id uuid NOT NULL REFERENCES public.interviews(id), consent_id uuid NOT NULL UNIQUE REFERENCES public.applicant_consents(id), format text NOT NULL CHECK (format IN ('in_person','phone','video')), capture_method text NOT NULL CHECK (capture_method IN ('microphone','tab_audio','upload')), duration numeric NOT NULL DEFAULT 0 CHECK (duration>=0), storage_path text, status text NOT NULL DEFAULT 'uploading' CHECK (status IN ('uploading','uploaded','transcribing','ready','failed','audio_deleted')), transcript text, ai_suggestions jsonb NOT NULL DEFAULT '[]'::jsonb, error text, error_status integer, processing_started_at timestamptz, attempts integer NOT NULL DEFAULT 0, retention_days integer NOT NULL DEFAULT 90 CHECK (retention_days IN (30,60,90,180)), audio_delete_after timestamptz NOT NULL DEFAULT (now()+interval '90 days'), audio_deleted_at timestamptz, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.interview_recordings TO authenticated;
GRANT ALL ON public.interview_recordings TO service_role;
REVOKE ALL ON public.interview_recordings FROM anon;
ALTER TABLE public.interview_recordings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read scoped interview recordings" ON public.interview_recordings FOR SELECT TO authenticated USING (public.can_read_compliance_record(org_id,store_id,applicant_id,auth.uid()));
CREATE INDEX interview_recordings_interview_idx ON public.interview_recordings(interview_id,created_at);
CREATE INDEX interview_recordings_cleanup_idx ON public.interview_recordings(audio_delete_after) WHERE audio_deleted_at IS NULL;
CREATE FUNCTION public.guard_recording_setting_changes() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.interview_recording_enabled IS DISTINCT FROM OLD.interview_recording_enabled OR NEW.recording_retention_days IS DISTINCT FROM OLD.recording_retention_days) AND auth.role() <> 'service_role' AND NOT (public.is_platform_admin(auth.uid()) OR public.has_org_role(NEW.org_id,auth.uid(),'group_admin') OR public.has_org_role(NEW.org_id,auth.uid(),'recruiter')) THEN RAISE EXCEPTION 'Only group admins and HR can change recording settings'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER guard_recording_setting_changes BEFORE UPDATE ON public.messaging_settings FOR EACH ROW EXECUTE FUNCTION public.guard_recording_setting_changes();
CREATE FUNCTION public.validate_interview_recording() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.interviews i JOIN public.applications a ON a.id=i.application_id JOIN public.applicant_consents c ON c.id=NEW.consent_id WHERE i.id=NEW.interview_id AND a.id=NEW.applicant_id AND a.org_id=NEW.org_id AND i.org_id=NEW.org_id AND a.dealership_id=NEW.store_id AND c.org_id=NEW.org_id AND c.applicant_id=NEW.applicant_id AND c.consent_type='recording' AND c.granted AND c.revoked_at IS NULL) THEN RAISE EXCEPTION 'Recording requires valid applicant consent for this interview'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_interview_recording BEFORE INSERT ON public.interview_recordings FOR EACH ROW EXECUTE FUNCTION public.validate_interview_recording();
CREATE POLICY "read private interview audio" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='interview-recordings' AND EXISTS (SELECT 1 FROM public.interview_recordings r WHERE r.storage_path=name AND public.can_read_compliance_record(r.org_id,r.store_id,r.applicant_id,auth.uid())));
REVOKE ALL ON FUNCTION public.guard_recording_setting_changes(),public.validate_interview_recording() FROM PUBLIC,anon,authenticated;